import { useState, useRef, useEffect } from "react";

const FONT_B64 = "";
const TEMPLATE_B64 = "";

const FIELDS = [
  { key: "applicantName", labelGu: "અરજદારનું નામ",       labelEn: "Applicant Full Name",    x: 104, y: 40,  maxW: 88 },
  { key: "address1",      labelGu: "સરનામું (line 1)",      labelEn: "Address Line 1",         x: 104, y: 47,  maxW: 88 },
  { key: "address2",      labelGu: "સરનામું (line 2)",      labelEn: "Address Line 2",         x: 40,  y: 54,  maxW: 152 },
  { key: "mobile",        labelGu: "મોબાઈલ",               labelEn: "Mobile Number",          x: 104, y: 61,  maxW: 88 },
  { key: "date",          labelGu: "તારીખ",                labelEn: "Date (DD/MM/YYYY)",      x: 104, y: 68,  maxW: 88 },
  { key: "toPerson",      labelGu: "પ્રતિ (નામ)",           labelEn: "To: Person Name",        x: 20,  y: 88,  maxW: 75 },
  { key: "toOffice",      labelGu: "મું. (કચેરી)",           labelEn: "Office / Place",         x: 27,  y: 94,  maxW: 68 },
  { key: "moje",          labelGu: "મોજે",                 labelEn: "Village (Moje)",         x: 42,  y: 105, maxW: 38 },
  { key: "taluko",        labelGu: "તાલુકો",               labelEn: "Taluko",                 x: 110, y: 105, maxW: 52 },
  { key: "jillo",         labelGu: "જ઼ ્ ઼ ો",                labelEn: "District (Jillo)",       x: 20,  y: 112, maxW: 55 },
  { key: "surveyNo",      labelGu: "સર્વે નં.",              labelEn: "Survey Number",          x: 108, y: 112, maxW: 38 },
  { key: "nakalCount",    labelGu: "ખરી નકલ નંગ",          labelEn: "No. of Copies",          x: 104, y: 146, maxW: 22 },
  { key: "mtrNo",         labelGu: "MTR No.",              labelEn: "MTR Number",             x: 44,  y: 204, maxW: 148 },
  { key: "onlineArjiNo",  labelGu: "ઓન લાઈન અરજી નં.",     labelEn: "Online Application No.", x: 64,  y: 210, maxW: 88 },
  { key: "mapaniDate",    labelGu: "માપણી તારીખ",          labelEn: "Mapani Date",            x: 155, y: 210, maxW: 44 },
  { key: "surveyorName",  labelGu: "સર્વેયર શ્રી નું નામ", labelEn: "Surveyor Name",          x: 62,  y: 216, maxW: 78 },
  { key: "depositAmt",    labelGu: "ડીપોઝીટ ₹",            labelEn: "Deposit Amount (₹)",     x: 64,  y: 222, maxW: 52 },
  { key: "proxyName",     labelGu: "નકલ - વતી (નામ)",      labelEn: "Proxy Name (optional)",  x: 92,  y: 237, maxW: 88 },
];

function isGujarati(t) { return /[\u0A80-\u0AFF]/.test(t); }
function isNumeric(t)   { return /^[\d\/\-.\s,₹+]+$/.test(t.trim()); }

async function translateToGujarati(text) {
  if (!text || !text.trim()) return text;
  if (isGujarati(text) || isNumeric(text)) return text.trim();
  try {
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 200,
        messages: [{ role: "user", content: `Translate the following into proper Gujarati script only. Return ONLY the Gujarati text, no explanation:\n\n"${text}"` }]
      })
    });
    const data = await res.json();
    return (data?.content?.[0]?.text || text).trim().replace(/^["\u201C]|["\u201D]$/g, "");
  } catch { return text; }
}

async function generatePDF(formData) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: "mm", format: "a4" });
  doc.addImage("data:image/jpeg;base64," + TEMPLATE_B64, "JPEG", 0, 0, 210, 297);
  doc.addFileToVFS("NotoSerifGujarati.ttf", FONT_B64);
  doc.addFont("NotoSerifGujarati.ttf", "NotoSerifGujarati", "normal");
  doc.setFont("NotoSerifGujarati", "normal");
  doc.setFontSize(10.5);
  doc.setTextColor(10, 10, 10);
  for (const f of FIELDS) {
    const val = formData[f.key];
    if (val && val.trim()) doc.text(val, f.x, f.y, { maxWidth: f.maxW });
  }
  doc.save("nakal_arji.pdf");
}

export default function App() {
  const [step, setStep]             = useState(0);
  const [formData, setFormData]     = useState({});
  const [input, setInput]           = useState("");
  const [messages, setMessages]     = useState([]);
  const [translating, setTranslating] = useState(false);
  const [done, setDone]             = useState(false);
  const [generating, setGenerating] = useState(false);
  const [pdfReady, setPdfReady]     = useState(false);
  const bottomRef = useRef(null);
  const inputRef  = useRef(null);

  useEffect(() => {
    if (window.jspdf) { setPdfReady(true); return; }
    const s = document.createElement("script");
    s.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
    s.onload = () => setPdfReady(true);
    document.head.appendChild(s);
  }, []);

  useEffect(() => {
    setMessages([
      { r: "bot", t: "🙏 નમસ્તે! નકલ મેળવવાની અરજી ભરવા માટે સ્વાગત છે.\nYou can type in Gujarati OR English — I will auto-translate to Gujarati." },
      { r: "bot", t: `📝 Field 1 of ${FIELDS.length}\n${FIELDS[0].labelGu}\n(${FIELDS[0].labelEn})` }
    ]);
  }, []);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
    setTimeout(() => inputRef.current?.focus(), 100);
  }, [messages, translating]);

  const addMsg = (msgs) => setMessages(p => [...p, ...msgs]);

  const handleSend = async () => {
    const raw = input.trim();
    if (!raw) return;
    addMsg([{ r: "user", t: raw }]);
    setInput("");
    setTranslating(true);
    const gu = await translateToGujarati(raw);
    setTranslating(false);
    const updated = { ...formData, [FIELDS[step].key]: gu };
    setFormData(updated);
    const confirm = isGujarati(raw) ? `✅ નોંધ્યું: ${gu}` : `✅ Translated → ${gu}`;
    const next = step + 1;
    if (next < FIELDS.length) {
      addMsg([
        { r: "bot", t: confirm },
        { r: "bot", t: `📝 Field ${next + 1} of ${FIELDS.length}\n${FIELDS[next].labelGu}\n(${FIELDS[next].labelEn})` }
      ]);
      setStep(next);
    } else {
      addMsg([{ r: "bot", t: confirm }, { r: "bot", t: "🎉 બધી વિગતો ભરાઈ ગઈ! All done.\nClick the button below to download your filled PDF." }]);
      setDone(true);
    }
  };

  const handleSkip = () => {
    addMsg([{ r: "user", t: "(skipped)" }]);
    const next = step + 1;
    if (next < FIELDS.length) {
      addMsg([{ r: "bot", t: `⏭ Skipped.\n📝 Field ${next + 1} of ${FIELDS.length}\n${FIELDS[next].labelGu}\n(${FIELDS[next].labelEn})` }]);
      setStep(next);
    } else {
      addMsg([{ r: "bot", t: "🎉 Done! Click below to download PDF." }]);
      setDone(true);
    }
  };

  const handlePDF = async () => {
    if (!pdfReady) { addMsg([{ r: "bot", t: "⏳ PDF library still loading, please wait..." }]); return; }
    setGenerating(true);
    addMsg([{ r: "bot", t: "⏳ Generating your filled PDF..." }]);
    await generatePDF(formData);
    setGenerating(false);
    addMsg([{ r: "bot", t: "✅ PDF downloaded! File name: nakal_arji.pdf" }]);
  };

  const pct = Math.round((step / FIELDS.length) * 100);

  const C = {
    page:    { minHeight:"100vh", background:"linear-gradient(160deg,#eef3f8 0%,#dde7f0 100%)", display:"flex", flexDirection:"column", alignItems:"center", padding:16, fontFamily:"'Segoe UI',sans-serif" },
    header:  { width:"100%", maxWidth:620, background:"#1a3a5c", borderRadius:"16px 16px 0 0", padding:"16px 22px", color:"white", boxShadow:"0 4px 18px rgba(0,0,0,0.22)" },
    h1:      { fontSize:19, fontWeight:700 },
    h2:      { fontSize:11.5, opacity:.75, marginTop:2 },
    bar:     { marginTop:12 },
    barLbl:  { fontSize:11, opacity:.7, marginBottom:4 },
    barBg:   { background:"rgba(255,255,255,0.2)", borderRadius:10, height:6 },
    barFill: (p) => ({ background:"#4fc3f7", borderRadius:10, height:6, width:`${p}%`, transition:"width 0.4s" }),
    chat:    { width:"100%", maxWidth:620, flex:1, background:"white", overflowY:"auto", maxHeight:"52vh", padding:16, display:"flex", flexDirection:"column", gap:10, boxShadow:"0 1px 8px rgba(0,0,0,0.08)" },
    bubbleWrap: (r) => ({ display:"flex", justifyContent: r==="user"?"flex-end":"flex-start" }),
    bubble: (r) => ({
      maxWidth:"80%", padding:"10px 14px", fontSize:13.5, lineHeight:1.65, whiteSpace:"pre-wrap",
      borderRadius: r==="user"?"18px 18px 4px 18px":"18px 18px 18px 4px",
      background: r==="user"?"#1a3a5c":"#f0f5fa",
      color: r==="user"?"white":"#1a2a3a",
      boxShadow:"0 1px 4px rgba(0,0,0,0.06)",
      fontFamily:"'Noto Serif Gujarati','Segoe UI',sans-serif"
    }),
    inputArea: { width:"100%", maxWidth:620, background:"#f7f9fc", borderTop:"1px solid #dde", padding:"12px 14px", display:"flex", gap:10, boxShadow:"0 4px 18px rgba(0,0,0,0.08)" },
    textarea: { flex:1, border:"1.5px solid #bcd", borderRadius:12, padding:"10px 14px", fontSize:14, resize:"none", height:46, fontFamily:"'Noto Serif Gujarati','Segoe UI',sans-serif", outline:"none" },
    skipBtn: { background:"#e4ecf4", border:"none", borderRadius:12, padding:"0 14px", cursor:"pointer", color:"#555", fontSize:12 },
    sendBtn: (dis) => ({ background:dis?"#aaa":"#1a3a5c", border:"none", borderRadius:12, color:"white", padding:"0 20px", cursor:"pointer", fontSize:20, fontWeight:700 }),
    pdfBtn: (dis) => ({ flex:1, background:dis?"#aaa":"linear-gradient(135deg,#1a3a5c,#2768a0)", border:"none", borderRadius:12, color:"white", padding:"14px", cursor:"pointer", fontSize:16, fontWeight:700, letterSpacing:.5, boxShadow:"0 4px 14px rgba(26,58,92,.35)" }),
    summary: { width:"100%", maxWidth:620, background:"#f0f7ff", border:"1px solid #c4dcf0", borderRadius:"0 0 14px 14px", padding:"10px 16px", marginTop:2 },
    sumHdr:  { fontSize:11, fontWeight:700, color:"#1a3a5c", marginBottom:6 },
    chips:   { display:"flex", flexWrap:"wrap", gap:6 },
    chip:    { background:"white", border:"1px solid #c8dff0", borderRadius:8, padding:"3px 9px", fontSize:11 },
    chipLbl: { color:"#1a3a5c", fontWeight:600 },
    footer:  { marginTop:8, fontSize:11, color:"#999", textAlign:"center" }
  };

  return (
    <div style={C.page}>
      <div style={C.header}>
        <div style={C.h1}>📄 નકલ મેળવવાની અરજી</div>
        <div style={C.h2}>પરિશિષ્ટ નં.-૫ · Chatbot Form Filler · Auto-translate to Gujarati</div>
        {!done && (
          <div style={C.bar}>
            <div style={C.barLbl}>Progress: {step} / {FIELDS.length} fields completed</div>
            <div style={C.barBg}><div style={C.barFill(pct)} /></div>
          </div>
        )}
      </div>

      <div style={C.chat}>
        {messages.map((m, i) => (
          <div key={i} style={C.bubbleWrap(m.r)}>
            <div style={C.bubble(m.r)}>{m.t}</div>
          </div>
        ))}
        {translating && (
          <div style={C.bubbleWrap("bot")}>
            <div style={{ ...C.bubble("bot"), color:"#888", fontStyle:"italic" }}>
              ⌛ Translating to Gujarati…
            </div>
          </div>
        )}
        <div ref={bottomRef} />
      </div>

      <div style={C.inputArea}>
        {!done ? (
          <>
            <textarea
              ref={inputRef}
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => { if(e.key==="Enter" && !e.shiftKey){ e.preventDefault(); handleSend(); }}}
              disabled={translating}
              placeholder={FIELDS[step] ? `${FIELDS[step].labelGu} — ${FIELDS[step].labelEn}` : ""}
              style={C.textarea}
            />
            <button onClick={handleSkip} style={C.skipBtn}>Skip</button>
            <button onClick={handleSend} disabled={translating || !input.trim()} style={C.sendBtn(translating || !input.trim())}>➤</button>
          </>
        ) : (
          <button onClick={handlePDF} disabled={generating} style={C.pdfBtn(generating)}>
            {generating ? "⏳ Generating PDF…" : "⬇️ Generate & Download Filled PDF"}
          </button>
        )}
      </div>

      {Object.keys(formData).length > 0 && (
        <div style={C.summary}>
          <div style={C.sumHdr}>📋 Collected Data Preview:</div>
          <div style={C.chips}>
            {FIELDS.filter(f => formData[f.key]).map(f => (
              <div key={f.key} style={C.chip}>
                <span style={C.chipLbl}>{f.labelGu}: </span>
                <span style={{ fontFamily:"'Noto Serif Gujarati',serif" }}>{formData[f.key]}</span>
              </div>
            ))}
          </div>
        </div>
      )}
      <div style={C.footer}>Powered by Claude API · Noto Serif Gujarati · jsPDF 2.5</div>
    </div>
  );
}
